302	/**
303	 * Dispatch CI and wait for it, or reuse a run that already exists, returning what
304	 * it concluded.
305	 *
306	 * A run that already exists for this commit is reused rather than duplicated. CI is
307	 * dispatched more than once for the same commit -- `create_pr`, `commit_and_push`,
308	 * and a person's `/agent` comment each start a validation -- and each used to run CI
309	 * again from scratch. The commit has not changed between them, so the verdict cannot
310	 * have. See `findExistingCiRun`.
311	 *
312	 * When there is something to wait for -- a run already going, or one this call
313	 * dispatched -- it says so through `notifyCiWaiting`, which holds the rules for when
314	 * that comment is worth a person's thread and when it is noise.
315	 *
316	 * A function rather than the body of `main`, so the one caller that must NOT run it
317	 * — a pull request whose own `.github/atomaton/` is broken — can skip it by not
318	 * calling it, instead of by an early return that would also skip writing the
319	 * checks and the comment.
320	 *
321	 * An empty `conclusion` means the run timed out, was cancelled, or was never
322	 * found. That is deliberately not an error here: `decideValidationOutcome` has a
323	 * verdict for it that dispatches nobody.
324	 */
325	function runCiAndWait(
326	  repo: string,
327	  number: string,
328	  workflow: string,
329	  branch: string,
330	  headSha: string,
331	  timeoutSeconds: number,
332	  askedByPerson: boolean,
333	): { conclusion: string; runUrl: string } {
334	  const runUrlFor = (id: number): string => `https://github.com/${repo}/actions/runs/${id}`;
335	
336	  // Filtered by `head_sha` server-side, because both callers below want only runs on
337	  // this commit and an unfiltered list is a bounded page: on a busy repository the
338	  // just-dispatched run is not on the first page, so the poll never finds it and
339	  // validation reports "no conclusion" and writes a failing check. Asking for the
340	  // commit is both correct and bounded.
341	  const listRuns = (): CiRun[] => {
342	    const listed = gh("api", `repos/${repo}/actions/runs?event=workflow_dispatch&head_sha=${headSha}`).stdout;
343	    const { workflow_runs = [] } = JSON.parse(listed || "{}") as { workflow_runs?: CiRun[] };
344	    return workflow_runs;
345	  };
346	
347	  // Reuse a CI run that already exists for this commit rather than starting a
348	  // second one. A cancelled run is not a verdict -- it was superseded, not judged --
349	  // so it is not reused and CI is dispatched again.
350	  const existing = findExistingCiRun(listRuns(), workflow, headSha);
351	  const reusable = existing?.status === "completed" && existing.conclusion && existing.conclusion !== "cancelled";
352	  if (reusable) {
353	    log(`reusing CI run ${existing.id} for ${headSha.slice(0, 7)}: ${existing.conclusion}`);
354	    return { conclusion: existing.conclusion!, runUrl: runUrlFor(existing.id) };
355	  }
356	
357	  // A run already going for this commit is waited for rather than duplicated. It is
358	  // the same commit and the same workflow, so a second run would answer the same
359	  // question twice.
360	  const alreadyRunning = existing !== undefined && existing.status !== "completed";
361	  const since = new Date().toISOString();
362	  // The person asked for a run and got silence so far; this is where a wait became
363	  // a fact, so this is where they are told. A reused run never reaches this, which
364	  // is the point -- see `notifyCiWaiting` for who is told and who is not.
365	  let notified = alreadyRunning;
366	  if (alreadyRunning) {
367	    log(`CI run ${existing.id} is already ${existing.status} for ${headSha.slice(0, 7)}; waiting for it`);
368	    notifyCiWaiting(repo, number, askedByPerson, runUrlFor(existing.id));
369	  } else {
370	    // `dispatchWorkflow` rather than a `gh workflow run` built here. This is the sixth
371	    // stand-in for the same hole — GitHub starts no workflow run for an event its own
372	    // token triggered — and the only one that cannot live in `adapters/actions/dispatch-targets.ts`,
373	    // because it has to RECOGNISE the run it started (see `pickDispatchedRun`: `gh
374	    // workflow run` returns nothing identifying, so the wait below matches on head sha
375	    // and start time). What it can share is the call itself.
376	    //
377	    // Fatal here, unlike everywhere else that dispatch is best-effort: this function's
378	    // whole purpose is the verdict CI gives, and there is none without a run.
379	    if (!dispatchWorkflow(`validate_pull_request: CI for ${branch}`, workflow, ["--repo", repo, "--ref", branch], log)) {
380	      process.exit(1);
381	    }
382	  }
383	
384	  const deadline = Date.now() + timeoutSeconds * 1000;
385	  while (Date.now() < deadline) {
386	    Bun.sleepSync(10_000);
387	    // A run that was already going is matched by id, not by `since`: it started
388	    // before this validation did, so `pickDispatchedRun`'s start-time filter would
389	    // never see it.
390	    const run = alreadyRunning
391	      ? listRuns().find((candidate) => candidate.id === existing.id)
392	      : pickDispatchedRun(listRuns(), headSha, since);
393	    if (!run) continue;
394	    // First sight of a run this call dispatched: say where to watch it, while it is
395	    // still going. A first sighting that is already completed says nothing -- "CI is
396	    // running" posted after it finished is the same lie the workflow-side comment
397	    // told -- and the verdict follows within seconds either way.
398	    if (!notified && run.status !== "completed") {
399	      notifyCiWaiting(repo, number, askedByPerson, runUrlFor(run.id));
400	      notified = true;
401	    }
402	    if (run.status !== "completed") continue;
403	    const conclusion = run.conclusion ?? "";
404	    log(`CI run ${run.id} concluded ${conclusion}`);
405	    return { conclusion, runUrl: runUrlFor(run.id) };
406	  }
407	
408	  log(`no conclusion within ${timeoutSeconds}s`);
409	  return { conclusion: "", runUrl: "" };
410	}
411	
412	function main(): void {
413	  const { values } = parseArgs({
414	    args: Bun.argv.slice(2),
415	    options: {
416	      repo: { type: "string" },
417	      number: { type: "string" },
418	      branch: { type: "string" },
419	      workflow: { type: "string" },
420	      "def-dir": { type: "string" },
421	      "deliverable-report": { type: "string" },
422	      "asked-by-person": { type: "string" },
423	      "timeout-seconds": { type: "string" },
424	    },
425	  });
426	
427	  const repo = values.repo ?? "";
428	  const branch = values.branch ?? "";
429	  const workflow = values.workflow ?? "";
430	  const defDir = values["def-dir"] ?? "";
431	  if (!repo || !branch || !workflow || !defDir) {
432	    console.error("usage: validate_pull_request.ts --repo owner/name --number N --branch B --workflow W --def-dir DIR");
433	    process.exit(1);
434	  }
435	
436	  // Read before anything is decided, and an absent file stops the run. The step
437	  // that writes it writes it unconditionally, including empty, so absence means the
438	  // step did not run — and "we did not check" must never be able to look like
439	  // "there was nothing wrong". Same reasoning as `required.known` below.
440	  const reportPath = values["deliverable-report"] ?? "";
441	  if (!reportPath) {
442	    console.error("usage: validate_pull_request.ts ... --deliverable-report FILE");
443	    process.exit(1);
444	  }
445	  if (!existsSync(reportPath)) {
446	    log(`cannot validate: no deliverable report at ${reportPath}`);
447	    process.exit(1);
448	  }
449	  const deliverableProblems = readFileSync(reportPath, "utf8")
450	    .split(/\r?\n/)
451	    .map((line) => line.trim())
452	    .filter(Boolean);
453	  if (deliverableProblems.length > 0) {
454	    log(`the deliverable is inconsistent (${deliverableProblems.length} problem(s)); CI will not be dispatched`);
455	  }
