export function commitsAdded(repo: string, before: string, after: string): string[] | null {
  if (!before || !after || /^0+$/.test(before)) return [];
  const { code, stdout } = gh("api", "--paginate", `repos/${repo}/compare/${before}...${after}`, "--jq", ".commits[].sha");
