 * A CI run that already exists for this commit, if one does.
 *
 * CI is dispatched more than once for the same commit. `create_pr` starts a
 * validation, `commit_and_push` starts another, and a person's `/agent` comment
 * starts a third -- and each of those used to run CI again from scratch. The commit
 * has not changed between them, so the verdict cannot have, and the second and third
 * runs bought nothing but runner time.
 *
 * Returns a run to reuse when one has concluded, and a run to wait for when one is
 * still going. Both are answers; a held or cancelled run is neither, and comes back
 * as `undefined` so the caller dispatches rather than reading it as either.
 *
 * A concluded run wins over a running one, whatever their times: the commit already
 * has a verdict, and waiting for a second run of the same workflow on the same commit
 * would learn nothing. Among equals the newest is taken, because a re-run is the one
 * somebody just asked for.
 */
export function findExistingCiRun(runs: CiRun[], workflow: string, headSha: string): RunRef | undefined {
  const candidates = runs
    .filter((run) => VERDICT_EVENTS.has(run.event))
    .filter((run) => run.head_sha === headSha)
    .filter((run) => run.path.endsWith(`/${workflow}`))
    .filter((run) => run.status !== "completed" || isVerdict(run.conclusion))
    .sort((a, b) => {
      const concluded = Number(b.status === "completed") - Number(a.status === "completed");
      return concluded !== 0 ? concluded : a.created_at < b.created_at ? 1 : -1;
